CREATE TABLE `agent_harness_interactions` (`id` text,`turn_id` text NOT NULL,`invocation_id` text NOT NULL,`parent_item_id` text NOT NULL DEFAULT "",`application_ref_json` text NOT NULL DEFAULT "",`artifact_refs_json` text NOT NULL DEFAULT "[]",`key` text NOT NULL,`kind` text NOT NULL,`schema_json` text NOT NULL,`presentation_json` text NOT NULL DEFAULT "",`status` text NOT NULL,`response_json` text NOT NULL DEFAULT "",`revision` integer NOT NULL,`created_at` datetime NOT NULL,`updated_at` datetime NOT NULL,PRIMARY KEY (`id`));
CREATE TABLE `agent_harness_invocations` (`id` text,`turn_id` text NOT NULL,`parent_item_id` text NOT NULL DEFAULT "",`capability_key` text NOT NULL,`definition_version` text NOT NULL DEFAULT "",`input_json` text NOT NULL DEFAULT "",`input_hash` text NOT NULL DEFAULT "",`execution_ref_id` text NOT NULL DEFAULT "",`status` text NOT NULL,`attempt` integer NOT NULL,`output_refs_json` text NOT NULL DEFAULT "[]",`error_code` text NOT NULL DEFAULT "",`error_detail` text NOT NULL DEFAULT "",`revision` integer NOT NULL,`created_at` datetime NOT NULL,`updated_at` datetime NOT NULL,PRIMARY KEY (`id`));
CREATE TABLE `agent_harness_items` (`id` text,`turn_id` text NOT NULL,`seq` integer NOT NULL,`kind` text NOT NULL,`status` text NOT NULL,`host_ref_kind` text NOT NULL DEFAULT "",`host_ref_id` text NOT NULL DEFAULT "",`run_id` text NOT NULL DEFAULT "",`invocation_id` text NOT NULL DEFAULT "",`parent_item_id` text NOT NULL DEFAULT "",`payload_json` text NOT NULL DEFAULT "{}",`created_at` datetime NOT NULL,`updated_at` datetime NOT NULL,PRIMARY KEY (`id`));
CREATE TABLE `agent_harness_managed_authority` (`id` text,`namespace` text NOT NULL,`generation` integer NOT NULL,`version` integer NOT NULL,PRIMARY KEY (`id`));
CREATE TABLE `agent_harness_managed_recovery` (`closure_hash` text NOT NULL DEFAULT "",`dispatch_id` text,`recovery_id` text NOT NULL,`turn_id` text NOT NULL,`record_json` text NOT NULL,PRIMARY KEY (`dispatch_id`));
CREATE TABLE `agent_harness_sessions` (`id` text,`host_thread_kind` text NOT NULL,`host_thread_id` text NOT NULL,`tenant_id` text NOT NULL,`actor_id` text NOT NULL,`revision` integer NOT NULL,`created_at` datetime NOT NULL,`updated_at` datetime NOT NULL,PRIMARY KEY (`id`));
CREATE TABLE `agent_harness_turns` (`id` text,`session_id` text NOT NULL,`host_turn_kind` text NOT NULL,`host_turn_id` text NOT NULL,`config_snapshot_id` text NOT NULL,`context_checkpoint_id` text NOT NULL DEFAULT "",`context_ref_id` text NOT NULL DEFAULT "",`context_generation` integer NOT NULL DEFAULT 0,`context_revision` integer NOT NULL DEFAULT 0,`context_lineage_hash` text NOT NULL DEFAULT "",`context_covered_through_source_id` text NOT NULL DEFAULT "",`context_content_hash` text NOT NULL DEFAULT "",`status` text NOT NULL,`revision` integer NOT NULL,`error_code` text NOT NULL DEFAULT "",`error_detail` text NOT NULL DEFAULT "",`created_at` datetime NOT NULL,`updated_at` datetime NOT NULL,PRIMARY KEY (`id`));
